window.docContents[197].resolve({"/9___-Structure-of-finite-dimensional-algebras/9___6___-Finite-abelian-categories/Projective-generator-_LPAR_progenerator_RPAR_/#Chapter9___Definition9___6___2":{"contents":"Definition 9.6.2. An object P of an abelian category \\mathcal{C} is said to be a projective generator (or progenerator) if it is projective and every object is a quotient of a multiple of P.\nFor example, in the category of modules over a ring A, the free module A is a projective generator.\n\n\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras\t9.6. Finite abelian categories\tProjective generator (progenerator)","header":"Projective generator (progenerator)","id":"/9___-Structure-of-finite-dimensional-algebras/9___6___-Finite-abelian-categories/Projective-generator-_LPAR_progenerator_RPAR_/#Chapter9___Definition9___6___2"},"/8___-Homological-algebra/8___2___-Tor-and-Ext-functors/Projective-resolution/#Chapter8___Definition8___2___1":{"contents":"Definition 8.2.1. A projective resolution of M is an exact sequence\n\n\\cdots \\to P_2 \\to P_1 \\to P_0 \\to M \\to 0\n\nsuch that all modules P_i, i \\geq 0, are projective.\n\n\n\n","context":"Introduction to Representation Theory\t8. Homological algebra\t8.2. Tor and Ext functors\tProjective resolution","header":"Projective resolution","id":"/8___-Homological-algebra/8___2___-Tor-and-Ext-functors/Projective-resolution/#Chapter8___Definition8___2___1"},"/2___-Basic-notions-of-representation-theory/2___2___-Algebras/Commutative-algebra/#Chapter2___Definition2___2___5":{"contents":"Definition 2.2.5. An algebra A is commutative if ab = ba for all a, b \\in A.\n\n\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.2. Algebras\tCommutative algebra","header":"Commutative algebra","id":"/2___-Basic-notions-of-representation-theory/2___2___-Algebras/Commutative-algebra/#Chapter2___Definition2___2___5"},"/3___-General-results-of-representation-theory/3___6___-Characters-of-representations/#chapter-03___section-3-6":{"contents":"\n\n\n\n\n\n","context":"Introduction to Representation Theory\t3. General results of representation theory","header":"3.6. Characters of representations","id":"/3___-General-results-of-representation-theory/3___6___-Characters-of-representations/#chapter-03___section-3-6"},"/6___-Quiver-representations/6___3___-Indecomposable-representations-of-the-quiver-___D_4___/Section-6___3-heading-and-introduction/#Chapter6___Section6___3_heading":{"contents":"\n\n","context":"Introduction to Representation Theory\t6. Quiver representations\t6.3. Indecomposable representations of the quiver $D_4$\tSection 6.3 heading and introduction","header":"Section 6.3 heading and introduction","id":"/6___-Quiver-representations/6___3___-Indecomposable-representations-of-the-quiver-___D_4___/Section-6___3-heading-and-introduction/#Chapter6___Section6___3_heading"}});
